def link_findings_to_audits(apps, schema_editor):
    """Bind existing findings to the one audit they can only have come from.

    A finding only knew its catalog requirement, shared by every audit on that
    framework. It is bound when a single audit in its domain assesses that
    requirement, or when its applied controls point to a single one of them.
    Ambiguous findings stay unbound and keep the old requirement-based matching.
    """
    Finding = apps.get_model("core", "Finding")
    FindingsAssessment = apps.get_model("core", "FindingsAssessment")
    RequirementAssessment = apps.get_model("core", "RequirementAssessment")

    findings = Finding.objects.filter(
        requirement_node__isnull=False, requirement_assessment__isnull=True
    )
    for finding in findings.iterator():
        candidates = list(
            RequirementAssessment.objects.filter(
                requirement_id=finding.requirement_node_id,
                compliance_assessment__folder_id=finding.folder_id,
            ).only("id", "compliance_assessment_id")
        )
        if len(candidates) > 1:
            control_audits = set(
                RequirementAssessment.objects.filter(
                    applied_controls__in=finding.applied_controls.all()
                ).values_list("compliance_assessment_id", flat=True)
            )
            candidates = [
                c for c in candidates if c.compliance_assessment_id in control_audits
            ]
        if len(candidates) == 1:
            Finding.objects.filter(id=finding.id).update(
                requirement_assessment_id=candidates[0].id
            )

    for binder in FindingsAssessment.objects.filter(compliance_assessment__isnull=True):
        audits = set(
            Finding.objects.filter(
                findings_assessment_id=binder.id, requirement_assessment__isnull=False
            ).values_list("requirement_assessment__compliance_assessment_id", flat=True)
        )
        if len(audits) == 1:
            FindingsAssessment.objects.filter(id=binder.id).update(
                compliance_assessment_id=audits.pop()
            )


